    u8 done; /* 0x38: set to 1 */
    u8 pad39;
    s16 frames; /* 0x3A */
    f32 speed; /* 0x3C: path length per second, times 60 */
    u8 pad40[0xC];
    s32 unk4C; /* 0x4C: 0 lets the switch go on */
